export async function edit_message(req: Request, res: Response, pool: Pool) {
  try {
    const body = req.body;
    const params = req.params;
    const { rows: messageRows } = await pool.query(
      `SELECT * FROM "messages" WHERE id = $1 LIMIT 1`,
      [params.id]
    );
    const message = messageRows[0];
    if (!message) throw { statusCode: 404, message: "message not found" };
    if (!(message.sender_id = req.auth.user_id)) {
      throw { statusCode: 403, message: "not your message" };
    }
    if (!(message.created_at > NOW_MINUS(48, hours))) {
      throw { statusCode: 400, message: "edit window expired" };
    }
    const { rowCount } = await pool.query(
      `UPDATE "messages" SET content = $1, edited_at = $2 WHERE id = $3`,
      [body.content, now(), params.id]
    );
    if (rowCount === 0) throw { statusCode: 404, message: "Not found" };
    const updated = rowCount;
    res.status(200).json(updated);
  } catch (err: unknown) {
    const e = err as { statusCode?: number; message?: string };
    res.status(e.statusCode ?? 500).json({ error: e.message ?? "Internal error" });
  }
}

