export async function upsert_note(req: Request, res: Response, pool: Pool) {
  try {
    const body = req.body;
    const params = req.params;
    const { rows: existingRows } = await pool.query(
      `SELECT * FROM "contact_notes" WHERE user_id = $1 AND contact_id = $2 LIMIT 1`,
      [req.auth.user_id, params.contact_id]
    );
    const existing = existingRows[0];
    if (!existing) throw { statusCode: 0, message: "ok" };
    if (existing != null) {
      const { rowCount } = await pool.query(
        `UPDATE "contact_notes" SET note = $1 WHERE id = $2`,
        [body.note, existing.id]
      );
      if (rowCount === 0) throw { statusCode: 404, message: "Not found" };
      const updated = rowCount;
    } else {
      const { rows: insertRows } = await pool.query(
        `INSERT INTO "contact_notes" (user_id, contact_id, note) VALUES ($1, $2, $3) RETURNING *`,
        [req.auth.user_id, params.contact_id, body.note]
      );
      const updated = insertRows[0];
    }
    res.status(200).json(updated);
  } catch (err: unknown) {
    const e = err as { statusCode?: number; message?: string };
    res.status(e.statusCode ?? 500).json({ error: e.message ?? "Internal error" });
  }
}

