export async function sync_appointment_to_calendar(req: Request, res: Response, pool: Pool) {
  try {
    const params = req.params;
    const { rows: appointmentRows } = await pool.query(
      `SELECT * FROM "appointments" WHERE id = $1 LIMIT 1`,
      [params.id]
    );
    const appointment = appointmentRows[0];
    if (!appointment) throw { statusCode: 404, message: "appointment not found" };
    const { rows: cal_syncRows } = await pool.query(
      `SELECT * FROM "calendar_syncs" WHERE user_id = $1 AND sync_enabled = $2 LIMIT 1`,
      [req.auth.user_id, TRUE]
    );
    const cal_sync = cal_syncRows[0];
    if (!cal_sync) throw { statusCode: 400, message: "no calendar connected" };
    const cal_event = calendar.create_event(cal_sync.access_token, appointment.title, appointment.start_at, appointment.end_at, appointment.location, appointment.notes);
    const { rows: insertRows } = await pool.query(
      `INSERT INTO "appointment_calendar_events" (appointment_id, user_id, external_event_id, calendar_provider) VALUES ($1, $2, $3, $4) RETURNING *`,
      [params.id, req.auth.user_id, cal_event.event_id, cal_sync.provider]
    );
    const link = insertRows[0];
    res.status(201).json(link);
  } catch (err: unknown) {
    const e = err as { statusCode?: number; message?: string };
    res.status(e.statusCode ?? 500).json({ error: e.message ?? "Internal error" });
  }
}

